   186→      select: {
   187→        id: true,
   188→        title: true,
   189→        completions: true,
   190→        status: true,
   191→        createdAt: true,
   192→      },
   193→      orderBy: { completions: "desc" },
   194→    }),
   195→    db.quizResponse.findMany({
   196→      where: {
   197→        shop,
   198→        createdAt: { gte: thirtyDaysAgo },
   199→        completedAt: { not: null },
   200→      },
   201→      select: { revenue: true, email: true },
   202→    }),
   203→    db.quizResponse.findMany({
   204→      where: {
   205→        shop,
   206→        createdAt: { gte: sixtyDaysAgo, lt: thirtyDaysAgo },
   207→        completedAt: { not: null },
   208→      },
   209→      select: { revenue: true, email: true },
   210→    }),
   211→  ]);
   212→
   213→  const currentRevenue = currentResponses.reduce((sum, r) => sum + r.revenue, 0);
   214→  const previousRevenue = previousResponses.reduce(
   215→    (sum, r) => sum + r.revenue,
   216→    0
   217→  );
   218→  const currentCompletions = currentResponses.length;
   219→  const previousCompletions = previousResponses.length;
   220→  const currentEmails = currentResponses.filter((r) => r.email).length;
   221→  const previousEmails = previousResponses.filter((r) => r.email).length;
   222→
   223→  function trend(current: number, previous: number): string {
   224→    if (previous === 0) return current > 0 ? "+100%" : "0%";
   225→    const pct = ((current - previous) / previous) * 100;
   226→    return `${pct >= 0 ? "+" : ""}${pct.toFixed(1)}%`;
