   238→      formatted: currentCompletions.toLocaleString(),
   239→      trend: trend(currentCompletions, previousCompletions),
   240→      up: currentCompletions >= previousCompletions,
   241→    },
   242→    emailsCaptured: {
   243→      value: currentEmails,
   244→      formatted: currentEmails.toLocaleString(),
   245→      trend: trend(currentEmails, previousEmails),
   246→      up: currentEmails >= previousEmails,
   247→    },
   248→    quizzes,
   249→    activeQuizCount: quizzes.filter((q) => q.status === "active").length,
   250→  };
   251→}
