import { useCallback } from "react";
import { json } from "react-router";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Banner,
  ProgressBar,
  List,
  IndexTable,
  Badge,
  Button,
  Box,
  Divider,
  useIndexResourceState,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { getDashboardStats } from "../services/quiz.server";

// --- Setup steps (static) ---

const setupSteps = [
  { label: "Create your first quiz", complete: true },
  { label: "Map products to answers", complete: false },
  { label: "Publish your quiz", complete: false },
];

// --- Status tone map ---

type BadgeTone = "success" | "attention" | "warning" | undefined;

const statusToneMap: Record<string, BadgeTone> = {
  active: "success",
  draft: "attention",
  paused: "warning",
  archived: undefined,
};

function formatStatus(status: string): string {
  return status.charAt(0).toUpperCase() + status.slice(1);
}

// --- Loader / Action ---

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  try {
    const data = await getDashboardStats(session.shop);
    return json({ data });
  } catch (error) {
    throw json({ error: "Failed to load dashboard data" }, { status: 500 });
  }
};

export const action = async ({ request }: ActionFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

// --- Hydrate Fallback (skeleton) ---

export function HydrateFallback() {
  return (
    <SkeletonPage title="Dashboard" primaryAction>
      <BlockStack gap="600">
        <InlineStack gap="400" align="start" wrap={false}>
          {[0, 1, 2, 3].map((i) => (
            <div key={i} style={{ flex: 1 }}>
              <Card>
                <BlockStack gap="200">
                  <SkeletonBodyText lines={1} />
                  <SkeletonDisplayText size="large" />
                  <SkeletonBodyText lines={1} />
                </BlockStack>
              </Card>
            </div>
          ))}
        </InlineStack>
        <Card>
          <SkeletonBodyText lines={3} />
        </Card>
        <Card>
          <SkeletonBodyText lines={6} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

// --- Components ---

function StatCard({
  label,
  value,
  trend,
  up,
  borderColor,
}: {
  label: string;
  value: string;
  trend: string;
  up: boolean;
  borderColor: string;
}) {
  return (
    <Card>
      <div style={{ borderTop: `3px solid ${borderColor}`, paddingTop: "4px" }}>
        <BlockStack gap="200">
          <Text as="p" variant="bodySm" tone="subdued">
            {label}
          </Text>
          <Text as="p" variant="headingXl" fontWeight="bold">
            {value}
          </Text>
          <Text
            as="p"
            variant="bodySm"
            tone={up ? "success" : "critical"}
          >
            {up ? "\u2191" : "\u2193"} {trend} vs last month
          </Text>
        </BlockStack>
      </div>
    </Card>
  );
}

function SetupChecklist({ onFinish }: { onFinish: () => void }) {
  const completedCount = setupSteps.filter((s) => s.complete).length;
  const totalCount = setupSteps.length;
  const progressPercent = Math.round((completedCount / totalCount) * 100);

  // If all steps are complete, don't show the banner
  if (completedCount === totalCount) return null;

  return (
    <Banner
      title="Complete your setup"
      tone="info"
      action={{ content: "Finish setup \u2192", onAction: onFinish }}
    >
      <BlockStack gap="300">
        <Text as="p" variant="bodySm" tone="subdued">
          {completedCount} of {totalCount} steps completed
        </Text>
        <ProgressBar progress={progressPercent} size="small" tone="primary" />
        <List type="number">
          {setupSteps.map((step, i) => (
            <List.Item key={i}>
              {step.label} {step.complete ? "\u2705" : ""}
            </List.Item>
          ))}
        </List>
      </BlockStack>
    </Banner>
  );
}

// --- Main Page ---

export default function Dashboard() {
  const { data } = useLoaderData<typeof loader>();
  const navigate = useNavigate();

  const handleCreateQuiz = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleViewAnalytics = useCallback(() => {
    navigate("/app/analytics");
  }, [navigate]);

  const handleFinishSetup = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleEditQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}`);
    },
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}/preview`);
    },
    [navigate],
  );

  const resourceName = { singular: "quiz", plural: "quizzes" };

  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(data.quizzes);

  const rowMarkup = data.quizzes.map(
    (
      quiz: {
        id: string;
        title: string;
        status: string;
        completions: number;
        createdAt: Date | string;
      },
      index: number,
    ) => (
      <IndexTable.Row
        id={quiz.id}
        key={quiz.id}
        selected={selectedResources.includes(quiz.id)}
        position={index}
      >
        <IndexTable.Cell>
          <InlineStack gap="300" blockAlign="center">
            <Text as="span" variant="headingMd">
              {"📊"}
            </Text>
            <BlockStack gap="050">
              <Text as="span" variant="bodyMd" fontWeight="semibold">
                {quiz.title}
              </Text>
              <Text as="span" variant="bodySm" tone="subdued">
                {quiz.status}
              </Text>
            </BlockStack>
          </InlineStack>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Badge tone={statusToneMap[quiz.status]}>
            {formatStatus(quiz.status)}
          </Badge>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {quiz.completions.toLocaleString()}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodySm" tone="subdued">
            {new Date(quiz.createdAt).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
              year: "numeric",
            })}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <InlineStack gap="200">
            <Button size="slim" onClick={() => handleEditQuiz(quiz.id)}>
              Edit
            </Button>
            <Button size="slim" variant="plain" onClick={() => handlePreviewQuiz(quiz.id)}>
              Preview
            </Button>
          </InlineStack>
        </IndexTable.Cell>
      </IndexTable.Row>
    ),
  );

  return (
    <Page
      title="Dashboard"
      subtitle="Welcome to QuizSnap"
      primaryAction={{
        content: "+ Create quiz",
        onAction: handleCreateQuiz,
      }}
      secondaryActions={[
        {
          content: "View analytics",
          onAction: handleViewAnalytics,
        },
      ]}
    >
      <BlockStack gap="600">
        {/* Statistics Cards Row */}
        <InlineStack gap="400" align="start" wrap={false}>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Attributed Revenue"
              value={data.revenue.formatted}
              trend={data.revenue.trend}
              up={data.revenue.up}
              borderColor="var(--p-color-bg-fill-success)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Quiz Completions"
              value={data.completions.formatted}
              trend={data.completions.trend}
              up={data.completions.up}
              borderColor="var(--p-color-bg-fill-info)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Active Quizzes"
              value={data.activeQuizCount.toString()}
              trend={""}
              up={true}
              borderColor="var(--p-color-text-emphasis)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Emails Captured"
              value={data.emailsCaptured.formatted}
              trend={data.emailsCaptured.trend}
              up={data.emailsCaptured.up}
              borderColor="var(--p-color-bg-fill-caution)"
            />
          </div>
        </InlineStack>

        {/* Setup Checklist Banner */}
        <SetupChecklist onFinish={handleFinishSetup} />

        <Divider />

        {/* Quiz List Table */}
        <Layout>
          <Layout.Section>
            <Card padding="0">
              <BlockStack>
                <Box padding="400">
                  <Text as="h2" variant="headingMd">
                    Your Quizzes
                  </Text>
                </Box>
                <IndexTable
                  resourceName={resourceName}
                  itemCount={data.quizzes.length}
                  selectedItemsCount={
                    allResourcesSelected ? "All" : selectedResources.length
                  }
                  onSelectionChange={handleSelectionChange}
                  headings={[
                    { title: "Quiz" },
                    { title: "Status" },
                    { title: "Completions", alignment: "end" },
                    { title: "Created" },
                    { title: "Actions" },
                  ]}
                >
                  {rowMarkup}
                </IndexTable>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

import { useState, useCallback, useEffect } from "react";
